/**
 * The privacy policy (CLAUDE.md §6 step 8: "no data leaves the device").
 * The single source for the in-app Privacy screen, docs/privacy-policy.md
 * and public/privacy.html (both generated by `npm run privacy`; a test
 * checks they're up to date).
 */

/**
 * Where people can reach the owner with questions. Must be filled in before
 * launch (the app stores require a contact). Empty: the policy says so.
 */
export const PRIVACY_CONTACT = '';

export const PRIVACY_UPDATED = '31 October 2026';

export type PrivacySection = { heading: string; paragraphs: string[] };

export const PRIVACY_SUMMARY =
  'Luna Beats does not collect, send or share any personal information. There are no accounts, ads, analytics or tracking. Everything you make in the app stays on your device.';

export const PRIVACY_SECTIONS: PrivacySection[] = [
  {
    heading: 'What stays on your device',
    paragraphs: [
      'Your settings, favorites, saved mixes and recordings are stored only on your phone (or, on the website, in your browser). We never receive them. Deleting the app (or clearing the site’s data in your browser) deletes them.',
    ],
  },
  {
    heading: 'Microphone and recordings',
    paragraphs: [
      'Luna Beats uses the microphone only while you record a lullaby or story, and only after you allow it. Recordings are saved on your device and are never uploaded. You can delete a recording at any time.',
    ],
  },
  {
    heading: 'Backups',
    paragraphs: [
      'A backup file is made on your device only when you tap “Make a backup”. You choose where it goes, for example Files, your cloud drive or email. We never receive it. It contains your recordings, so keep it somewhere private.',
    ],
  },
  {
    heading: 'No internet needed',
    paragraphs: [
      'The app works fully offline. It does not contact any server of ours, and it contains no advertising, analytics or tracking code.',
      'The website version is served by GitHub Pages. GitHub may keep standard server logs, such as IP addresses, as described in GitHub’s privacy statement. The website itself sends nothing about you anywhere.',
    ],
  },
  {
    heading: 'Children',
    paragraphs: [
      'Luna Beats is made for parents and caregivers to use for their babies. It does not collect any information from or about children.',
    ],
  },
  {
    heading: 'Changes',
    paragraphs: [
      'If this policy changes, the new version will be posted here with a new date. We will never start collecting personal information without asking you first.',
    ],
  },
];

export function privacyContactLine(contact = PRIVACY_CONTACT): string {
  return contact
    ? `Questions? Contact ${contact}.`
    : 'Questions? Contact details will be added here before the app is released.';
}

/** The policy as Markdown (docs/privacy-policy.md). */
export function privacyMarkdown(contact = PRIVACY_CONTACT): string {
  return [
    '# Luna Beats privacy policy',
    '',
    `_Last updated: ${PRIVACY_UPDATED}_`,
    '',
    `**${PRIVACY_SUMMARY}**`,
    '',
    ...PRIVACY_SECTIONS.flatMap((s) => [
      `## ${s.heading}`,
      '',
      ...s.paragraphs.flatMap((p) => [p, '']),
    ]),
    '## Contact',
    '',
    privacyContactLine(contact),
    '',
  ].join('\n');
}

const escape = (t: string) =>
  t.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

/** The policy as a standalone web page (public/privacy.html), in the night theme. */
export function privacyHtml(contact = PRIVACY_CONTACT): string {
  const sections = PRIVACY_SECTIONS.map(
    (s) =>
      `    <h2>${escape(s.heading)}</h2>\n${s.paragraphs.map((p) => `    <p>${escape(p)}</p>`).join('\n')}`,
  ).join('\n');
  return `<!doctype html>
<html lang="en">
  <head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    <title>Privacy policy · Luna Beats</title>
    <meta name="description" content="${escape(PRIVACY_SUMMARY)}" />
    <style>
      body { margin: 0; background: #14173a; color: #ece6f6; font: 17px/1.6 system-ui, -apple-system, sans-serif; }
      main { max-width: 640px; margin: 0 auto; padding: 32px 20px 64px; }
      h1 { font-size: 28px; margin: 0 0 4px; }
      h2 { font-size: 19px; margin: 32px 0 8px; color: #f2d59b; }
      p { margin: 0 0 12px; color: #b4add3; }
      .summary { color: #ece6f6; font-weight: 600; background: #1c1f45; border: 1px solid #343970; border-radius: 16px; padding: 16px; }
      .updated { color: #9a94be; font-size: 14px; }
      a { color: #b8a9e8; }
    </style>
  </head>
  <body>
    <main>
    <h1>Luna Beats privacy policy</h1>
    <p class="updated">Last updated: ${escape(PRIVACY_UPDATED)}</p>
    <p class="summary">${escape(PRIVACY_SUMMARY)}</p>
${sections}
    <h2>Contact</h2>
    <p>${escape(privacyContactLine(contact))}</p>
    <p><a href="./">Open Luna Beats</a></p>
    </main>
  </body>
</html>
`;
}
